package com.example.data.local

object DuaReferenceLocalization {
    fun getLocalizedReference(duaId: Int, language: String): String? {
        return when (language) {
            "Hausa" -> getHausaReference(duaId)
            "Yoruba" -> getYorubaReference(duaId)
            "Igbo" -> getIgboReference(duaId)
            "Arabic" -> getArabicReference(duaId)
            else -> null
        }
    }

    private fun getHausaReference(id: Int): String? {
        return when (id) {
            1 -> "Falalar ambaton Allah (Zikiri) tana da girma kwarai a Musulunci:\n1. Allah Yana ambaton bawan da ke ambatonsa ('Ku ambace Ni Zan ambace ku' - Al-Baqarah 2:152).\n2. Zikiri yana sanya natsuwar zuciya da samun salama ('Lallai da ambaton Allah zuciyoyi ke natsuwa' - Ar-Ra'd 13:28).\n3. Annabi (SAW) ya kwatanta mai zikiri da mai rai, wanda ba ya yi kuma da matacce (Sahih Al-Bukhari).\n4. Yana goge zunubai, yana korar Shaidan, kuma yana kawo kariya da albarka a rayuwa.\nMadogara: Surah Al-Baqarah 2:152, Surah Al-Ahzab 33:41-42, Sahih Al-Bukhari 11/208, Sahih Muslim 1/539. Hisnul Muslim Babi na 1."
            41 -> "Karanta wannan idan an tashi daga barci yana nuna godiya mai girma ga rayuwar jiki da ta ruhi, tare da amincewa cewa Allah Shi kadai ke bayar da rai bayan mutuwa kuma zuwa gare Shi ne makoma ta karshe.\nMadogara: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 11/113, Muslim 4/2083."
            2 -> "Wanda duk ya fadi wannan da rana yana mai yakini da shi, kuma ya mutu a ranar kafin yamma, to yana daya daga cikin 'yan Aljanna; idan kuma ya fadi haka da daddare yana mai yakini da shi, ya kuma mutu kafin gari ya waye, to yana daya daga cikin 'yan Aljanna.\nMadogara: Al-Bukhari 7/150."
            3 -> "Wanda duk ya karanta wannan sau uku da safe da kuma sau uku da yamma, babu abin da zai cutar da shi a ranar ko daren, yana zama garkuwa mai karfi daga dukkan fitinu da cutarwa na farat daya.\nMadogara: Abu Dawud 4/323, At-Tirmidhi 5/465."
            4 -> "Wanda duk ya karanta wannan sau uku da safe da kuma sau uku da yamma, ya zama wajibi a kan Allah ya yardar da shi a Ranar Kiyama, ya cika zuciyarsa da gamsuwa da aminci.\nMadogara: Abu Dawud 4/318, At-Tirmidhi 5/465."
            5 -> "Ana karantawa kafin barci domin mika rai gaba daya ga Allah lokacin barci (wanda a cikin Alkur'ani ake kiransa da karamar mutuwa) da kuma neman kariya ta Ubangiji a cikin dare.\nMadogara: Al-Bukhari (Fathul-Bari 11/113), Muslim 4/2083."
            6 -> "Wannan addu'ar tana nuna murna ga lafiyar jiki, farfadowar ruhi, da kuma babbar ni'ima ta samun izinin ambaton Allah da bauta masa bayan bude idanu a sabuwar rana.\nMadogara: At-Tirmidhi 5/473."
            7 -> "Wanda duk ya karanta wannan lokacin shiga masallaci, Shaidan zai ce: 'An kare shi daga gare ni sauran ranar,' yana tabbatar da kariyar ruhi yayin da yake cikin gidan Allah.\nMadogara: Abu Dawud 1/127, Al-Albani a Sahih Abu Dawud."
            8 -> "Ana karantawa yayin fita daga masallaci domin neman albarkar Allah, arziki, lafiya, da abinci na halal yayin komawa ga harkokin duniya da ayyuka.\nMadogara: Muslim 1/494."
            42 -> "Annabi (tsira da amincin Allah su tabbata a gare shi) ya ce: 'Wanda duk ya saka tufafi kuma ya fadi wannan, za a gafarta masa dukkan zunubansa na baya,' yana nuna yadda aiki mai sauki na sanya tufafi zai zama silar gafarar zunubai lokacin da aka hada shi da godiya.\nMadogara: Abu Dawud, At-Tirmidhi, Ibn Majah."
            10 -> "Ambatar sunan Allah kafin cin abinci yana hana Shaidan rabawa ko dauke albarka da abinci na abincinku, yana tabbatar da cewa abincin yana kawo matsakaicin lafiya da lada.\nMadogara: Abu Dawud 3/347, At-Tirmidhi 4/288."
            11 -> "Idan mutum ya manta ambatar sunan Allah a farko, to karanta wannan lokacin da ya tuna zai katse kasancewar Shaidan nan take kuma ya mayar da albarkar abincin.\nMadogara: Abu Dawud 3/347, At-Tirmidhi 4/288."
            12 -> "Annabi (tsira da amincin Allah su tabbata a gare shi) ya ce: 'Wanda duk ya ci abinci ya fadi wannan a karshensa, za a gafarta masa dukkan zunubansa na baya,' yana jaddada darajar godiya ta kaskantar da kai.\nMadogara: At-Tirmidhi, Abu Dawud, Ibn Majah."
            13 -> "Idan mutum ya fadi wannan lokacin fita daga gida, ana ce masa: 'An shiryar da kai, an tsare ka, kuma an kiyaye ka,' kuma shaidanu suna nisanta da shi, suna kiyaye shi a tafiyarsa.\nMadogara: Abu Dawud 4/325, At-Tirmidhi 5/490."
            14 -> "Karantawa lokacin shiga gida yana tabbatar da cewa aminci, albarka, da kariya ta mala'iku suna tare da ku, kuma Shaidan ya gane ba shi da wurin zama ko abinci a daren.\nMadogara: Abu Dawud 4/325."
            15 -> "Ana karantawa yayin hawa abin hawa don tafiya. Yana kaskantar da matafiyi ta hanyar tabbatar da cewa dukkan ababen hawa sun hore mana ne kawai da falalar Allah, kuma yana tuna mana tafiyarmu ta karshe zuwa gare Shi.\nMadogara: Muslim 2/978."
            16 -> "Annabi Muhammad (tsira da amincin Allah su tabbata a gare shi) ya kasance yana yawaita karanta wannan addu'ar, domin tana duba sauki daga damuwar hankali, rashin aiki na jiki, nauyin kudi, da zaluncin mutane.\nMadogara: Al-Bukhari 7/158."
            17 -> "Da aka sani da 'Addu'ar Damuwa'. Annabi (tsira da amincin Allah su tabbata a gare shi) ya kasance yana maimaita wadannan kalmomi lokacin tsananin wahala ko gaggawa don neman rahamar Allah da kwantar da hankalinsa.\nMadogara: Al-Bukhari 8/154, Muslim 4/2092."
            18 -> "Yana daga cikin Sunnar Annabi mai tabbata neman gafarar Allah sau uku nan take bayan kammala kowace sallah ta farilla don cike duk wani rashin natsuwa ko tawaya lokacin bautar.\nMadogara: Muslim 1/414."
            19 -> "Annabi (tsira da amincin Allah su tabbata a gare shi) ya ce: 'Wanda duk ya karanta wannan bayan kowace sallah, za a gafarta masa zunubansa koda sun kai kumfan teku yawa.'\nMadogara: Muslim 1/418."
            20 -> "Atishawa ni'ima ce ta jiki daga Allah. Karanta yabo, mayar da martani ga dan uwa da addu'ar rahama, da bayar da shiriya shine kyakkyawan tsari da ke gina soyayya ta zamantakewa da 'yan uwantaka.\nMadogara: Al-Bukhari 7/125."
            21 -> "Ana karantawa don neman kariya ta Ubangiji daga kazantattun ruhohi da ke cikin bandaki.\nMadogara: Al-Bukhari 1/45, Muslim 1/283."
            22 -> "Ana karantawa yayin fita don gode wa Allah da Ya sauƙaƙa nauyin jiki da kuma neman tsarkakar ruhi.\nMadogara: Abu Dawud, At-Tirmidhi, Ibn Majah."
            23 -> "Fadin wannan yana da kyau kwarai kafin yin alwala.\nMadogara: Abu Dawud, Ibn Majah, Ahmad."
            24 -> "Ana bude kofofin Aljanna guda takwas ga duk wanda ya karanta wannan bayan ya kammala alwala.\nMadogara: Muslim 1/209, At-Tirmidhi 1/78."
            25 -> "Ana karantawa don murkushe fushi na farat daya da mayar da kwanciyar hankali.\nMadogara: Al-Bukhari 7/99, Muslim 4/2015."
            26 -> "Ana fada yayin ziyartar mara lafiya don kawo masa sanyin gwiwa da bege.\nMadogara: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 10/118."
            27 -> "Addu'a mai zurfi ta neman rahama da shiga kabari cikin girma.\nMadogara: Muslim 2/663."
            28 -> "Annabi (tsira da amincin Allah su tabbata a gare shi) ya koyar da wannan don yanke shawara a kan kowane lamari mai muhimmanci.\nMadogara: Al-Bukhari 7/162."
            29 -> "Karanta wannan lokacin da masifa ta faru yana kawo kwanciyar hankali, lada, da kuma musanyawa mafi alheri.\nMadogara: Muslim 2/632."
            30 -> "Annabi (tsira da amincin Allah su tabbata a gare shi) ya kasance yana karanta wannan addu'ar fiye da sau 100 a kullum.\nMadogara: Al-Bukhari, Muslim 4/2075."
            31 -> "Kyakkyawar addu'ar neman sauki wajen biyan bashi da samun wadatar kudi.\nMadogara: At-Tirmidhi 5/560."
            32 -> "Ana fada lokacin da ake ruwan sama don rokon Allah albarka da amfani maimakon barna.\nMadogara: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 2/518."
            33 -> "Yana bayyana cewa ruwan sama yana zuwa ne kawai daga falalar Allah da rahamarSa.\nMadogara: Al-Bukhari 1/205, Muslim 1/83."
            34 -> "Ana karantawa lokacin da aka ji tsawa don nuna kaskantar da kai da tsoron girman Allah.\nMadogara: Muwatta Malik 2/992."
            35 -> "Yana rokon ruwan sama mai amfani da kuma kariya daga guguwa mai barna.\nMadogara: Abu Dawud 4/326, Ibn Majah 2/1228."
            36 -> "Samun lada mai yawa (kyakkyawan lada miliyan daya, goge zunubai miliyan daya) don ambaton Allah a cikin kasuwanni masu cunkoso.\nMadogara: At-Tirmidhi 5/291."
            37 -> "Annabi ya kasance yana neman tsari ga Hassan da Husayn da wadannan kalmomi.\nMadogara: Al-Bukhari 4/119."
            38 -> "Addu'a mai muhimmanci don kiyaye tauhidi na gaskiya da tsarkakar niyya.\nMadogara: Ahmad 4/403, Al-Albani a Sahihul-Jami' 3/233."
            39 -> "Yana mika gaisuwa ga mamata da rokon kariya/lafiya ga rayayyu da mamata duka.\nMadogara: Muslim 2/671, Ibn Majah 1/494."
            40 -> "Aika salati ga Annabi Muhammad yana ninka lada sau goma kuma yana daukaka daraja.\nMadogara: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 6/408."
            78 -> "Addu'a ce mai albarka da ke tattaro neman gyaran addini, rayuwar duniya, gobe kiyama, da kuma rokon sanya rayuwa ta kasance karuwar alheri da mutuwa ta kasance hutu daga dukkan sharri.\nMadogara: Sahih Muslim, Littafi na 17, Hadisi na 1472 (Muslim 2720)."
            79 -> "Addu'a ce ingantacciya ta yaye damuwa da bakin ciki da neman sanya Alkur'ani ya zama furen zuciya da hasken kirji.\nMadogara: Musnad Ahmad 1/391, Ibn Hibban 3/253, Sahih Al-Kalim Al-Tayyib 124."
            80 -> "Addu'a ce ta neman biyan bashi, kariya daga talauci da yabon Allah da kyawawan sunayensa.\nMadogara: Sahih Muslim 4/2084 (Hadisi 2713)."
            81 -> "Addu'a ce ta neman kyakkyawan karshe a dukkan al'amuran rayuwa da kariya daga kankantar duniya da azabar lahira.\nMadogara: Musnad Ahmad 4/181, Sahih Ibn Hibban 949, Al-Hakim 3/591."
            82 -> "Addu'a ce ta neman tabbatuwa a kan addini da gaskiya, da neman zuciya salima da harshe mai gaskiya.\nMadogara: Sunan An-Nasa'i 1304, At-Tirmidhi 3407, Musnad Ahmad 17114."
            83 -> "Addu'a ce ta neman tsari daga ilimin da ba ya amfani, zuciya maras tsoron Allah, rai maras koshi, da addu'ar da ba a amsawa.\nMadogara: Sahih Muslim 4/2088 (Hadisi 2722), An-Nasa'i 5442, Abu Dawud 1548."
            else -> "Madogara: Al-Bukhari, Muslim da sauran littattafai ingantattu."
        }
    }

    private fun getYorubaReference(id: Int): String? {
        return when (id) {
            1 -> "Àwọn oore ati virtues ti ranti Allāhu (Zikiri) ga pupọ ninu Ẹ̀sìn Islam:\n1. Allāhu n ranti ẹru ti o ba ranti Rẹ ('Ẹ ranti Mi, Emi yoo ranti yin' - 2:152).\n2. Zikiri n mu alaafia ati itẹlọrun ba ọkan ('Daju ninu iranti Allāhu ni awọn ọkan ti n ni ifọkanbalẹ' - 13:28).\n3. Ojisẹ Allāhu (SAW) fi ẹni ti n ranti Allāhu we alaaye, ẹni ti ko si ranti Rẹ we oku.\n4. Ó n rọ ẹṣẹ ji, o n le Ṣaitan jinna, o si n so ẹru pọ mọ Ọlọrun Rẹ.\nÌtọ́kasí: Surah Al-Baqarah 2:152, Surah Al-Ahzab 33:41-42, Sahih Al-Bukhari, Sahih Muslim. Hisnul Muslim Ori 1."
            41 -> "Sísọ eyi lẹyin jidide n ṣe afihan ọpẹ nla fun imularada jiki ati ti ẹmi, ni jẹwọ pe Allāhu nikan lo n funni ni iye lẹyin iku ati pe sọdọ Rẹ ni atun-kójọ kẹhin wà.\nÌtọ́kasí: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 11/113, Muslim 4/2083."
            2 -> "Ẹnikẹni ti o ba sọ eyi lakoko ọsan pẹlu igbagbọ to daju, ti o si ku ni ọjọ yẹn ṣaaju irọlẹ, yoo wa ninu awọn eniyan Ọgba Rere; ti o ba si sọ ọ ni alẹ pẹlu igbagbọ to daju, ti o si ku ṣaaju owurọ, yoo wa ninu awọn eniyan Ọgba Rere.\nÌtọ́kasí: Al-Bukhari 7/150."
            3 -> "Ẹnikẹni ti o ba ka eyi ni igba mẹta ni owurọ ati igba mẹta ni irọlẹ, ko si nkan ti yoo pa a lara ni ọjọ tabi alẹ yẹn, o jẹ gẹgẹ bi apata ti o lagbara lọwọ gbogbo aburu ojiji ati ipalara.\nÌtọ́kasí: Abu Dawud 4/323, At-Tirmidhi 5/465."
            4 -> "Ẹnikẹni ti o ba ka eyi ni igba mẹta ni owurọ ati igba mẹta ni irọlẹ, o di dandan fun Allāhu lati mu inu rẹ dun ni Ọجinde, ti yoo fi itẹlọrun ati alaafia kun ọkan rẹ.\nÌtọ́kasí: Abu Dawud 4/318, At-Tirmidhi 5/465."
            5 -> "A n sọ eyi ṣaaju sisun lati fi ẹmi rẹ le Allāhu lọwọ patapata lakoko oorun (ti a tọka si ninu Alkur'ani gẹgẹ bi iku kekere) ati lati wa aabo Rẹ jakejado alẹ.\nÌtọ́kasí: Al-Bukhari (Fathul-Bari 11/113), Muslim 4/2083."
            6 -> "Adura yi n ṣe afihan ilera jiki, isoji ẹmi, ati oore nla ti lile ranti Allāhu ati jọsin fun Un lẹyin ṣiṣi oju si ọjọ tuntun.\nÌtọ́kasí: At-Tirmidhi 5/473."
            7 -> "Ẹnikẹni ti o ba ka eyi nigba ti o ba n wọ masallaci, satani yoo sọ pe: 'A ti daabobo rẹ lọwọ mi fun iyoku ọjọ naa,' ni idaniloju aabo ẹmi lakoko ti o wa ninu ile Allāhu.\nÌtọ́kasí: Abu Dawud 1/127, Al-Albani ni Sahih Abu Dawud."
            8 -> "A n sọ eyi nigba ti a ba n jade kuro ni masallaci lati wa oore, ounjẹ, ilera, ati ipese halal lọdọ Allāhu bi o ṣe n pada si awọn ọrọ aye ati awọn iṣẹ rẹ.\nÌtọ́kasí: Muslim 1/494."
            42 -> "Ojisẹ (ki ikẹ ati ọla Allāhu ma ba a) sọ pe: 'Ẹnikẹni ti o ba wọ aṣọ ti o si sọ eyi, gbogbo awọn ẹṣẹ rẹ ti o ti kọja ni a o rọ lẹṣẹ ji,' eyi n fihan bi sísọ adura pẹlu ọpẹ ṣe le jẹ ọna idariji ẹṣẹ.\nÌtọ́kasí: Abu Dawud, At-Tirmidhi, Ibn Majah."
            10 -> "Sísọ orukọ Allāhu ṣaaju ki a to jẹun n dènà satani lati jẹun pẹlu rẹ tabi gbe ibukun ati ounjẹ rẹ lọ, ni idaniloju pe ounjẹ naa n mu ilera ati ẹsan to pọ julọ wa.\nÌtọ́kasí: Abu Dawud 3/347, At-Tirmidhi 4/288."
            11 -> "Ti eniyan ba gbagbe lati ranti orukọ Allāhu ni ibẹrẹ, sisọ eyi nigbati o ba ranti n dènà satani lesekese ati mu ibukun ounjẹ naa pada wa.\nÌtọ́kasí: Abu Dawud 3/347, At-Tirmidhi 4/288."
            12 -> "Ojisẹ (ki ikẹ ati ọla Allāhu ma ba a) sọ pe: 'Ẹnikẹni ti o ba jẹun ti o si sọ eyi ni opin rẹ, gbogbo awọn ẹṣẹ rẹ ti o ti kọja ni a o rọ lẹṣẹ ji,' ni tẹnumọ riri ọpẹ nla.\nÌtọ́kasí: At-Tirmidhi, Abu Dawud, Ibn Majah."
            13 -> "Nigbati eniyan ba sọ eyi nigba ti o ba n jade kuro ni ile rẹ, a o sọ fun u pe: 'A ti tọ ọ si ọna tọ, a ti daabobo rẹ, a si ti fipamọ rẹ,' awọn satani yoo si jinna si i.\nÌtọ́kasí: Abu Dawud 4/325, At-Tirmidhi 5/490."
            14 -> "Sísọ eyi nigba ti a ba n wọle n ṣe idaniloju pe alaafia, ibukun, ati aabo awọn angẹli n ba ọ gbe, satani yoo si mọ pe ko si ibugbe tabi ounjẹ fun u ni alẹ yẹn.\nÌtọ́kasí: Abu Dawud 4/325."
            15 -> "A n sọ eyi nigba ti a ba bẹrẹ irin-ajo eyikeyi. O n rẹ arin-rin-ajo silẹ nipa jidide pe gbogbo ọna gbigbe ni Allāhu tẹ luba fun wa pẹlu aanu Rẹ.\nÌtọ́kasí: Muslim 2/978."
            16 -> "Ojisẹ Allāhu (ki ikẹ ati ọla Allāhu ma ba a) lo n sọ eyi nigbagbogbo, nitori pe o dènà ibanujẹ, ọlẹ, gbese, ati lile ti eniyan.\nÌtọ́kasí: Al-Bukhari 7/158."
            17 -> "Adura fun ẹni ti o wa ninu ipọnju. Ojisẹ Allāhu maa n sọ eyi lakoko awọn ipọnju nla lati ranti aanu Allāhu ati lati mu alaafia ba ọkan rẹ.\nÌtọ́kasí: Al-Bukhari 8/154, Muslim 4/2092."
            18 -> "Sunnah ti o daju ni lati tọrọ gafara lọdọ Allāhu ni igba mẹta lẹsẹkẹsẹ lẹyin sallah kọọkan lati ṣe atunṣe si eyikeyi aipe lakoko isin.\nÌtọ́kasí: Muslim 1/414."
            19 -> "Ojisẹ Allāhu sọ pe: 'Ẹnikẹni ti o ba sọ eyi lẹyin sallah kọọkan, gbogbo awọn ẹṣẹ rẹ ni a o rọ lẹṣẹ ji paapaa ti o ba pọ to foomu okun.'\nÌtọ́kasí: Muslim 1/418."
            20 -> "Atishawa jẹ ibukun jiki lati ọdọ Allāhu. Ṣíṣe afẹri Rẹ, didahun pẹlu aanu, ati bibere tọna jẹ iyipo koriya nla fun ifẹ ati yan uwantaka.\nÌtọ́kasí: Al-Bukhari 7/125."
            21 -> "A n ka eyi lati tọrọ aabo Allāhu lọwọ awọn ẹmi buruku ninu baluwe.\nÌtọ́kasí: Al-Bukhari 1/45, Muslim 1/283."
            22 -> "A n sọ eyi lẹyin ti a ba jade lati dupẹ lọwọ Allāhu fun imukuro ẹru jiki ati tọrọ gafara.\nÌtọ́kasí: Abu Dawud, At-Tirmidhi, Ibn Majah."
            23 -> "Sísọ eyi ni iṣeduro gidi ṣaaju ṣiṣe alwala.\nÌtọ́kasí: Abu Dawud, Ibn Majah, Ahmad."
            24 -> "Awọn ilẹkun mẹjọ ti Ọgba Rere ni a o ṣii silẹ for ẹnikẹni ti o ba ka eyi lẹyin alwala rẹ.\nÌtọ́kasí: Muslim 1/209, At-Tirmidhi 1/78."
            25 -> "A n sọ eyi lati pa ibinu ojiji ati lati mu alaafia ba ọkan pada.\nÌtọ́kasí: Al-Bukhari 7/99, Muslim 4/2015."
            26 -> "A n fọhùn yi nigba ti a ba bẹ alaisan wo lati fun u ni ireti ati itunu.\nÌtọ́kasí: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 10/118."
            27 -> "Adura nla fun aanu ati titẹsi kabari pẹlu ọla nla.\nÌtọ́kasí: Muslim 2/663."
            28 -> "Ojisẹ Allāhu kọ wa ni eyi fun ṣiṣe ipinnu lori eyikeyi ọrọ pataki.\nÌtọ́kasí: Al-Bukhari 7/162."
            29 -> "Sísọ eyi lakoko masiba n mu alaafia ati ẹsan rere wa pẹlu rọpo t'o dara ju u lọ.\nÌtọ́kasí: Muslim 2/632."
            30 -> "Ojisẹ Allāhu maa n sọ eyi ju igba ọgọrun lọ lojumọ.\nÌtọ́kasí: Al-Bukhari, Muslim 4/2075."
            31 -> "Adura t'o dara fun irọrun lati san gbese ati gbigba ominira ti inawo.\nÌtọ́kasí: At-Tirmidhi 5/560."
            32 -> "A n sọ eyi lakoko ojo lati tọrọ ibukun ati anfani rẹ ju ipalara lọ.\nÌtọ́kasí: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 2/518."
            33 -> "O n jẹrii pe ojo n rọ nitori oore-ọfẹ ati aanu Allāhu nikan.\nÌtọ́kasí: Al-Bukhari 1/205, Muslim 1/83."
            34 -> "A n sọ eyi nigba ti a ba gbọ àrá lati fi irẹlẹ ati tsoro giriki Allāhu han.\nÌtọ́kasí: Muwatta Malik 2/992."
            35 -> "Adura fun ojo t'o dara ati aabo lọwọ gẹgẹ gẹgẹ t'o lagbara.\nÌtọ́kasí: Abu Dawud 4/326, Ibn Majah 2/1228."
            36 -> "Gbigba ẹsan nla (oore miliyan kan, piparẹ ẹṣẹ miliyan kan) nitori ranti Allāhu ni ọja t'o ni cunkoso.\nÌtọ́kasí: At-Tirmidhi 5/291."
            37 -> "Ojisẹ Allāhu maa n lo eyi to seek protection for Hassan and Husayn.\nÌtọ́kasí: Al-Bukhari 4/119."
            38 -> "Adura pataki lati kiyaye tauhidi gidi ati mimọ ọkan.\nÌtọ́kasí: Ahmad 4/403, Al-Albani ni Sahihul-Jami' 3/233."
            39 -> "Gbigba alaafia fun awọn oku ati tọrọ alaafia fun awọn alaaye ati oku duka.\nÌtọ́kasí: Muslim 2/671, Ibn Majah 1/494."
            40 -> "Aika salati fun Ojisẹ Allāhu n sọ ẹsan di ilopo mẹwa ati gbigbe ipo ga.\nÌtọ́kasí: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 6/408."
            78 -> "Adura ajẹmọ-gbogbo ni eyi ti o n ro atunṣe ẹsin, aye, ọrun, ati bibere ki igbesi aye jẹ alekun oore ati pe ki iku jẹ isimi kuro ninu gbogbo aburu.\nÌtọ́kasí: Sahih Muslim, Iwe 17, Hadisi 1472 (Muslim 2720)."
            79 -> "Adura fun imukuro aibalẹ ati ibanujẹ ati kikọ Al-Kur’ani ni idunnu ọkan.\nÌtọ́kasí: Musnad Ahmad 1/391, Ibn Hibban 3/253, Sahih Al-Kalim Al-Tayyib 124."
            80 -> "Adura fun isanwo gbese, àbò kuro ninu osi ati iyin pẹlu orukọ Allāhu gigun.\nÌtọ́kasí: Sahih Muslim 4/2084 (Hadisi 2713)."
            81 -> "Adura fun igbẹhin rere ninu gbogbo ọrọ aye ati àbò kuro ninu itiju aye ati iya ọrun.\nÌtọ́kasí: Musnad Ahmad 4/181, Sahih Ibn Hibban 949, Al-Hakim 3/591."
            82 -> "Adura fun iduroṣinṣin lori ẹsin ati ọna mọọmọ, ati bibere ọkan mimọ ati ahọn olootọ.\nÌtọ́kasí: Sunan An-Nasa'i 1304, At-Tirmidhi 3407, Musnad Ahmad 17114."
            83 -> "Adura fun aabo lọwọ mọ ti ko ni alafia, ọkan ti ko ni tẹriba, ẹmi ti ko ni tẹ lọrun, ati adura ti ko ni gba.\nÌtọ́kasí: Sahih Muslim 4/2088 (Hadisi 2722), An-Nasa'i 5442, Abu Dawud 1548."
            else -> "Ìtọ́kasí: Al-Bukhari, Muslim ati awọn iwe ingantattu miran."
        }
    }

    private fun getIgboReference(id: Int): String? {
        return when (id) {
            1 -> "Uru dị n'ịtụgharị uche na ichere Chineke (Dhikr) dị ukwuu n'Islam:\n1. Chineke na-echeta ohu nke na-echeta Ya ('Cheta m ka m cheta gị' - 2:152).\n2. Dhikr na-eweta udo na afọ ojuju n'obi ('N'ezie, n'icheta Chineke ka obi na-enwe udo' - 13:28).\n3. Onye Ozi Chineke (SAW) jiri onye na-echeta Chineke tụnyere onye dị ndụ, ma jiri onye na-adịghị echeta Ya tụnyere onye nwụrụ anwụ.\n4. Ọ na-agbaghara mmehie, na-achụ Ekwensu, ma na-eweta nchebe na ngọzi.\nEbe nsinyere: Surah Al-Baqarah 2:152, Surah Al-Ahzab 33:41-42, Sahih Al-Bukhari, Sahih Muslim. Hisnul Muslim Isi nke 1."
            41 -> "Ịgụ nke a mgbe a mụrụ anya na-egosi ekele miri emi maka mbilite n'ọnwụ nke anụ ahụ na nke ime mmụọ, na-ekwupụta na ọ bụ naanị Chineke na-enye ndụ mgbe ọnwụ gasịrị na n'aka Ya ka mbilite n'ọnwụ ikpeazụ dị.\nEbe nsinyere: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 11/113, Muslim 4/2083."
            2 -> "Onye ọ bụla nke kwuru nke a n'ehihie na nkwenye siri ike, ma nwụọ n'ụbọchị ahụ tupu anyasị, ọ ga-eso ná ndị Paradaịs; ọ bụrụkwa na mmadụ ekwuo ya n'abalị na nkwenye siri ike, ma nwụọ tupu ụtụtụ, ọ ga-eso ná ndị Paradaịs.\nEbe nsinyere: Al-Bukhari 7/150."
            3 -> "Onye ọ bụla nke gụrụ nke a ugboro atọ n'ụtụtụ na ugboro atọ n'anyasị, ọ dịghị ihe ga-emerụ ha ahụ n'ụbọchị ma ọ bụ abalị ahụ, ọ na-eje ozi dị ka ọta siri ike megide ihe mberede niile.\nEbe nsinyere: Abu Dawud 4/323, At-Tirmidhi 5/465."
            4 -> "Onye ọ bụla nke gụrụ nke a ugboro atọ n'ụtụtụ na ugboro atọ n'anyasị, ọ na-aghọ ọrụ dị n'aka Chineke ime ka obi tọọ ya ụtọ n'Ụbọchị Mbilite n'Ọnwụ, na-eme ka obi ya jupụta na afọ ojuju na udo.\nEbe nsinyere: Abu Dawud 4/318, At-Tirmidhi 5/465."
            5 -> "A na-agụ ya tupu e hie ụra iji nye mkpụrụ obi gị niile n'aka Chineke n'oge ụra (nke a kpọrọ ọnwụ nta na Quran) na ịchọ nchebe Ya n'abalị niile.\nEbe nsinyere: Al-Bukhari (Fathul-Bari 11/113), Muslim 4/2083."
            6 -> "Ekpere a na-eme ememe ahụ ike, mbilite n'ọnwụ ime mmụọ, na nnukwu ngọzi nke a kwere ka anyị cheta Chineke ma feo Ya mgbe anyị mepere anya anyị n'ụbọchị ọhụrụ.\nEbe nsinyere: At-Tirmidhi 5/473."
            7 -> "Onye ọ bụla nke gụrụ nke a mgbe ọ na-abanye n'ụlọ ekpere, Setan na-asị: 'Echebela ya n'aka m n'ụbọchị fọdụrụnụ,' na-eme ka nchebe ime mmụọ dị n'ime ụlọ Chineke.\nEbe nsinyere: Abu Dawud 1/127, Al-Albani na Sahih Abu Dawud."
            8 -> "A na-agụ ya mgbe a na-apụ n'ụlọ ekpere iji rịọ ngọzi Chineke, nri, ahụ ike, na ihe oriri kwesịrị ekwesị ka ị na-alaghachi n'ihe banyere ụwa na ọrụ gị.\nEbe nsinyere: Muslim 1/494."
            42 -> "Onye Amụma (udo na ngọzi nke Chineke dịrị ya) sịrị: 'Onye ọ bụla yi uwe ma kwuo nke a, a ga-agbaghara mmehie ya niile gara aga,' na-egosi otú uwe yiri nwere ike isi bụrụ ụzọ isi nweta mgbaghara mmehie mgbe ekele so ya.\nEbe nsinyere: Abu Dawud, At-Tirmidhi, Ibn Majah."
            10 -> "Ịkpọ aha Chineke tupu e rie nri na-egbochi Setan ịkọrọ gị nri ma ọ bụ wepụ ngọzi na uru nri gị, na-eme ka nri ahụ wetara gị ahụ ike na ụgwọ ọrụ kachasị ukwuu.\nEbe nsinyere: Abu Dawud 3/347, At-Tirmidhi 4/288."
            11 -> "Ọ bụrụ na mmadụ chefuru ịkpọ aha Chineke ná mmalite, ịgụ nke a mgbe ha chetara na-achụpụ Setan ozugbo ma weghachi ngọzi nri ahụ.\nEbe nsinyere: Abu Dawud 3/347, At-Tirmidhi 4/288."
            12 -> "Onye Amụma (udo na ngọzi nke Chineke dịrị ya) sịrị: 'Onye ọ bụla riri nri ma kwuo nke a na njedebe ya, a ga-agbaghara mmehie ya niile gara aga,' na-emesi ike nnukwu uru nke ekele dị umeala n'obi dị.\nEbe nsinyere: At-Tirmidhi, Abu Dawud, Ibn Majah."
            13 -> "Mgbe mmadụ kwuru nke a mgbe ọ na-apụ n'ụlọ ya, a na-asị ya: 'A dula gị, chebe gị, ma wepụ gị,' Setan na-agbakwa ọsọ n'ebe ọ nọ.\nEbe nsinyere: Abu Dawud 4/325, At-Tirmidhi 5/490."
            14 -> "Ịgụ nke a mgbe ị na-abanye n'ụlọ na-eme ka udo, ngọzi, na nchebe nke ndị mmụọ ozi soro gị bi, Setan ga-amarakwa na ọ dịghị nri ma ọ bụ ebe obibi maka ya.\nEbe nsinyere: Abu Dawud 4/325."
            15 -> "A na-agụ nke a mgbe a na-amalite njem ọ bụla. Ọ na-eme ka onye njem dị umeala n'obi site n'ịghọta na ọ bụ naanị amara Chineke na-enye anyị ụgbọ niile.\nEbe nsinyere: Muslim 2/978."
            16 -> "Onye Ozi nke Chineke (udo na ngọzi nke Chineke dịrị ya) na-agụ nke a ugboro ugboro n'ihi na ọ na-achụpụ mwute, umengwụ, ụgwọ, na mmetọ enyi.\nEbe nsinyere: Al-Bukhari 7/158."
            17 -> "Ekpere maka onye nọ n'ahụhụ. Onye Ozi Chineke na-agụ nke a mgbe ọ bụla ahụhụ siri ike pụtara iji rịọ ebere Chineke na udo n'obi ya.\nEbe nsinyere: Al-Bukhari 8/154, Muslim 4/2092."
            18 -> "Ọ bụ Sunnah doro anya ịrịọ Chineke mgbaghara mgbe niile ugboro atọ ozugbo e kpechara ekpere sallah ọ bụla iji dozie adịghị ike ọ bụla.\nEbe nsinyere: Muslim 1/414."
            19 -> "Onye Ozi Chineke sịrị: 'Onye ọ bụla kwuru nke a mgbe sallah gachara, a ga-agbaghara mmehie ya niile ọ bụrụgodị na ha pọrọ ka ụfụfụ osimiri.'\nEbe nsinyere: Muslim 1/418."
            20 -> "Ịmị uzere bụ ngọzi anụ ahụ sitere n'aka Chineke. Ịgụ otuto Ya, ịzaghachi na ebere, na idu ndú bụ usoro magburu onwe ya nke na-eweta ịhụnanya na nwanne.\nEbe nsinyere: Al-Bukhari 7/125."
            21 -> "A na-agụ ya iji rịọ nchebe Chineke pụọ na mmụọ ruru arụ na-adị n'ụlọ ịsa ahụ.\nEbe nsinyere: Al-Bukhari 1/45, Muslim 1/283."
            22 -> "A na-agụ ya mgbe a na-apụ iji kelee Chineke maka iwepụ arọ anụ ahụ na ịrịọ mgbaghara.\nEbe nsinyere: Abu Dawud, At-Tirmidhi, Ibn Majah."
            23 -> "Ịgụ nke a na-atụ aro nke ukwuu tupu e mee alwala.\nEbe nsinyere: Abu Dawud, Ibn Majah, Ahmad."
            24 -> "A ga-emeghe ụzọ ámá asatọ nke Paradaịs maka onye ọ bụla gụrụ nke a mgbe alwala ya gasịrị.\nEbe nsinyere: Muslim 1/209, At-Tirmidhi 1/78."
            25 -> "A na-agụ ya iji kpochapụ iwe na-atụghị anya ya na iji weghachi udo n'obi.\nEbe nsinyere: Al-Bukhari 7/99, Muslim 4/2015."
            26 -> "A na-ekwu nke a mgbe a na-eleta onye ọrịa iji nye ya olileanya na nkasi obi.\nEbe nsinyere: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 10/118."
            27 -> "Nnukwu ekpere maka ebere na ntinye n'ili n'ụzọ dị ùgwù.\nEbe nsinyere: Muslim 2/663."
            28 -> "Onye Ozi Chineke kụziiri anyị nke a maka ịme mkpebi n'ihe ọ bụla dị mkpa.\nEbe nsinyere: Al-Bukhari 7/162."
            29 -> "Ịgụ nke a n'oge ahụhụ na-eweta udo na ụgwọ ọrụ kacha mma.\nEbe nsinyere: Muslim 2/632."
            30 -> "Onye Ozi Chineke na-agụ nke a karịrị ugboro otu narị kwa ụbọchị.\nEbe nsinyere: Al-Bukhari, Muslim 4/2075."
            31 -> "Ekpere mara mma maka ịkwụ ụgwọ n'ụzọ dị mfe na inweta nnwere onwe ego.\nEbe nsinyere: At-Tirmidhi 5/560."
            32 -> "A na-agụ ya mgbe mmiri na-ozuzo iji rịọ ngọzi Chineke ma ghara ibibi ihe.\nEbe nsinyere: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 2/518."
            33 -> "Ọ na-egosi na mmiri ozuzo na-ezo naanị site n'amara Chineke na ebere Ya.\nEbe nsinyere: Al-Bukhari 1/205, Muslim 1/83."
            34 -> "A na-agụ ya mgbe anụrụ égbè eluigwe iji gosi ịdị umeala n'obi na egwu Chineke.\nEbe nsinyere: Muwatta Malik 2/992."
            35 -> "Ekpere maka mmiri ozuzo dị mma na nchebe pụọ na guguwa siri ike.\nEbe nsinyere: Abu Dawud 4/326, Ibn Majah 2/1228."
            36 -> "Inweta ụgwọ ọrụ dị ukwuu (ezigbo ọrụ nde kwuru nde, nhichapụ mmehie nde) maka icheta Chineke n'ahịa.\nEbe nsinyere: At-Tirmidhi 5/291."
            37 -> "Onye Ozi Chineke na-eji nke a achọ nchebe maka Hassan na Husayn.\nEbe nsinyere: Al-Bukhari 4/119."
            38 -> "Ekpere dị mkpa iji hụ na ofufe Chineke dị ọcha na ezi ebumnuche.\nEbe nsinyere: Ahmad 4/403, Al-Albani na Sahihul-Jami' 3/233."
            39 -> "Ịziga udo nye ndị nwụrụ anwụ na ịrịọ nchebe/udo maka ndị dị ndụ na ndị nwụrụ anwụ.\nEbe nsinyere: Muslim 2/671, Ibn Majah 1/494."
            40 -> "Ịziga ngọzi nye Onye Ozi Chineke na-abawanye ụgwọ ọrụ gị okpukpu iri ma bulie ọkwa gị elu.\nEbe nsinyere: Al-Bukhari, duba Al-Asqalani, Fathul-Bari 6/408."
            78 -> "Ekpere a bụ nnukwu ekpere maka idozi okpukpe, ụwa, na ndụ ikpeazụ, yana ịrịọ ka ndụ bụrụ mmụba nke ihe ọma niile na ka ọnwụ bụrụ ntụsara ahụ pụọ n'ihe ọjọọ niile.\nEbe nsinyere: Sahih Muslim, Akwụkwọ 17, Hadịs 1472 (Muslim 2720)."
            79 -> "Ekpere maka iwepụ nchegbu na ihe nwute, na ime ka Qur'an bụrụ ìhè nke obi.\nEbe nsinyere: Musnad Ahmad 1/391, Ibn Hibban 3/253, Sahih Al-Kalim Al-Tayyib 124."
            80 -> "Ekpere maka ikwụ ụgwọ, nchebe pụọ n'ịda ogbenye na otuto Chineke na aha Ya mara mma.\nEbe nsinyere: Sahih Muslim 4/2084 (Hadịs 2713)."
            81 -> "Ekpere maka ezi njedebe n'ihe niile na nchebe pụọ n'ihere nke ụwa a na ahụhụ ikpeazụ.\nEbe nsinyere: Musnad Ahmad 4/181, Sahih Ibn Hibban 949, Al-Hakim 3/591."
            82 -> "Ekpere maka nkwụsi ike n'okpukpe na ezi omume, na ịrịọ obi dị ọcha na ire eziokwu.\nEbe nsinyere: Sunan An-Nasa'i 1304, At-Tirmidhi 3407, Musnad Ahmad 17114."
            83 -> "Ekpere maka nchebe pụọ n'ihe mmụta na-abaghị uru, n'obi na-atụghị egwu, n'obere obi na-enweghị afọ ojuju, na n'ekpere a na-aza gị.\nEbe nsinyere: Sahih Muslim 4/2088 (Hadịs 2722), An-Nasa'i 5442, Abu Dawud 1548."
            else -> "Ebe nsinyere: Al-Bukhari, Muslim na akwụkwọ ndị ọzọ doro anya."
        }
    }

    private fun getArabicReference(id: Int): String? {
        return when (id) {
            1 -> "فضل الذكر عظيم في الإسلام:\n١. أن الله تعالى يذكر من ذكره (فاذكروني أذكركم - البقرة 152).\n٢. الذكر يورث طمأنينة القلب (ألا بذكر الله تطمئن القلوب - الرعد 28).\n٣. شبه النبي ﷺ الذي يذكر ربه بالحي والذي لا يذكره بالميت (صحيح البخاري).\n٤. يطرد الشيطان، ويحط الخطايا، ويجلب الحفظ والبركة.\nالمرجع: سورة البقرة 2:152، سورة الأحزاب 33:41-42، صحيح البخاري 11/208، صحيح مسلم 1/539. حصن المسلم الباب الأول."
            41 -> "قراءة هذا الذكر عند الاستيقاظ تعبر عن الشكر العميق لإحياء البدن والروح، والاعتراف بأن الله وحده يحيي الموتى وإليه النشور.\nالمرجع: البخاري، وانظر العسقلاني فتح الباري 11/113، ومسلم 4/2083."
            2 -> "من قالها موقناً بها حين يمسي فمات من ليلته دخل الجنة، وكذلك إذا أصبح.\nالمرجع: البخاري 7/150."
            3 -> "من قالها ثلاثاً إذا أصبح وثلاثاً إذا أمسى لم يضره شيء في ذلك اليوم أو تلك الليلة، وهي درع قوي ضد فجاءة النقم والمكاره.\nالمرجع: أبو داود 4/323، والترمذي 5/465."
            4 -> "من قالها ثلاثاً حين يصبح وثلاثاً حين يمسي كان حقاً على الله أن يرضيه يوم القيامة ويملأ قلبه طمأنينة وسلاماً.\nالمرجع: أبو داود 4/318، والترمذي 5/465."
            5 -> "تقال قبل النوم لتفويض الروح بالكامل إلى الله تعالى أثناء النوم (الذي يسمى بالموت الأصغر في القرآن) وطلب حمايته الإلهية طوال الليل.\nالمرجع: البخاري فتح الباري 11/113، ومسلم 4/2083."
            6 -> "هذا الدعاء يعبر عن معاني العافية البدنية والروحية، والنعمة العظيمة بأن يؤذن للعبد بذكر الله تعالى وعبادته عند فتح عينيه على يوم جديد.\nالمرجع: الترمذي 5/473."
            7 -> "من قال هذا عند دخول المسجد قال الشيطان: 'حُفظ مني سائر اليوم'، وهو يضمن الحراسة الروحية طوال التواجد في بيت الله.\nالمرجع: أبو داود 1/127، وصححه الألباني."
            8 -> "تقال عند الخروج من المسجد لطلب البركة، والرزق، والعافية من فضل الله تعالى مع العودة إلى شؤون الدنيا ومشاغلها.\nالمرجع: مسلم 1/494."
            42 -> "قال النبي صلى الله عليه وسلم: 'من لبس ثوباً فقال هذا غفر له ما تقدم من ذنبه'، وهو يبين كيف يمكن للفعل المعتاد أن يتحول لسبب المغفرة بالحمد والشكر.\nالمرجع: أبو داود، والترمذي، وابن ماجه."
            10 -> "التسمية قبل الأكل تمنع الشيطان من مشاركة العبد طعامه أو نزع البركة منه، مما يضمن نفع الطعام وبركته.\nالمرجع: أبو داود 3/347، والترمذي 4/288."
            11 -> "إذا نسي العبد التسمية في أول الطعام، فإن قول هذا عند تذكره يطرد الشيطان فوراً ويعيد بركة الطعام.\nالمرجع: أبو داود 3/347، والترمذي 4/288."
            12 -> "قال النبي صلى الله عليه وسلم: 'من أكل طعاماً فقال هذا في آخره غفر له ما تقدم من ذنبه'، وهو تأكيد على فضل شكر النعمة.\nالمرجع: الترمذي، وأبو داود، وابن ماجه."
            13 -> "من قالها عند خروجه من بيته قيل له: 'هُديت وكُفيت ووُقيت' وتنحى عنه الشيطان وحُفظ في مسيرته.\nالمرجع: أبو داود 4/325، والترمذي 5/490."
            14 -> "قراءتها عند الدخول تضمن نزول السلام والبركة وحضور الملائكة، ويعلم الشيطان أنه لا مبيت له ولا عشاء في هذا البيت.\nالمرجع: أبو داود 4/325."
            15 -> "تقال عند البدء في أي سفر، وفيها استحضار لعظمة نعم الله تعالى بتسخير وسائل الركوب وتذكير بالسفر الأكبر والرجوع إليه سبحانه.\nالمرجع: مسلم 2/978."
            16 -> "كان النبي صلى الله عليه وسلم يكثر من هذا الدعاء لأنه يجمع الاستعاذة من الهموم النفسية، والكسل البدني، والضيق المالي، وقهر الرجال.\nالمرجع: البخاري 7/158."
            17 -> "يُعرف بدعاء الكرب، وكان النبي صلى الله عليه وسلم يكرر هذه الكلمات عند الشدائد العظام لاستنزال رحمة الله وتثبيت قلبه.\nالمرجع: البخاري 8/154، ومسلم 4/2092."
            18 -> "من السنة المؤكدة الاستغفار ثلاثاً فور الفراغ من كل صلاة مكتوبة لجبر أي نقص أو تشتت للذهن أثناء العبادة.\nالمرجع: مسلم 1/414."
            19 -> "قال النبي صلى الله عليه وسلم: 'من سبح الله في دبر كل صلاة ثلاثاً وثلاثين... غفرت خطاياه وإن كانت مثل زبد البحر'.\nالمرجع: مسلم 1/418."
            20 -> "العطاس نعمة بدنية من الله، وحمده وتشميت العطس بالدعاء له بالرحمة ثم رده بالهداية وصلاح البال يوثق روابط المحبة والأخوة.\nالمرجع: البخاري 7/125."
            21 -> "تقال للاستعاذة بالله وحمايته من الأرواح الخبيثة والأقذار في أماكن قضاء الحاجة.\nالمرجع: البخاري 1/45، ومسلم 1/283."
            22 -> "تقال عند الخروج لطلب مغفرة الله تعالى والاعتراف بفضله وعافيته وتخفيف ثقل البدن.\nالمرجع: أبو داود، والترمذي، وابن ماجه."
            23 -> "يستحب قولها عند الشروع في الوضوء.\nالمرجع: أبو داود، وابن ماجه، وأحمد."
            24 -> "تفتح أبواب الجنة الثمانية لمن قال هذا الذكر بعد إسباغ الوضوء.\nالمرجع: مسلم 1/209، والترمذي 1/78."
            25 -> "تقال لإطفاء الغضب المفاجئ واسترجاع السكينة وهدوء النفس.\nالمرجع: البخاري 7/99، ومسلم 4/2015."
            26 -> "تقال عند عيادة المريض لإدخال الأنس على قلبه وتذكيره بأن المرض طهور ومطهر من الذنوب.\nالمرجع: البخاري مع فتح الباري 10/118."
            27 -> "دعاء عظيم بالرحمة والمغفرة والتوسيع على الميت في قبره.\nالمرجع: مسلم 2/663."
            28 -> "علمنا النبي صلى الله عليه وسلم هذا الدعاء لطلب الخيرة من الله في كل الأمور والقرارات الهامة.\nالمرجع: البخاري 7/162."
            29 -> "قراءتها عند نزول المصيبة تجلب الصبر والسكينة، وتوجب الخلف الصالح والأجر العظيم.\nالمرجع: مسلم 2/632."
            30 -> "كان النبي صلى الله عليه وسلم يستغفر ويتوب في اليوم أكثر من مائة مرة.\nالمرجع: البخاري، ومسلم 4/2075."
            31 -> "دعاء عظيم لتيسير قضاء الديون ونيل الاستقلال المالي والرزق الحلال.\nالمرجع: الترمذي 5/560."
            32 -> "تقال عند نزول المطر لسؤال الله تعالى أن يجعله مطر خير وبركة ونفع لا مطر هدم وعذاب.\nالمرجع: البخاري مع فتح الباري 2/518."
            33 -> "تذكير بأن نزول المطر إنما هو بمحض فضل الله ورحمته سبحانه لا بنجم ولا نوء.\nالمرجع: البخاري 1/205، ومسلم 1/83."
            34 -> "تقال عند سماع الرعد استشعاراً لعظمة الباري وخوفاً من سطوته وجلاله سبحانه.\nالمرجع: موطأ مالك 2/992."
            35 -> "سؤال الله تعالى خير الرياح النافعة والاستعاذة من شر عواصفها المهلكة.\nالمرجع: أبو داود 4/326، وابن ماجه 2/1228."
            36 -> "فيها أجر عظيم مضاعف (كتابة ألف ألف حسنة ومحو ألف ألف سيئة) لذكر الله تعالى في مواطن الغفلة والانشغال بالبيع والشراء.\nالمرجع: الترمذي 5/291."
            37 -> "كان النبي صلى الله عليه وسلم يعوذ بها الحسن والحسين لطلب الحفظ التام لهما.\nالمرجع: البخاري 4/119."
            38 -> "دعاء عظيم للمحافظة على التوحيد الخالص وسلامة النية من الشرك الخفي والظاهر.\nالمرجع: أحمد 4/403، وصححه الألباني."
            39 -> "فيها السلام على الموتى وسؤال الله تعالى العافية والسلامة للأحياء والأموات.\nالمرجع: مسلم 2/671، وابن ماجه 1/494."
            40 -> "الصلاة على النبي صلى الله عليه وسلم توجب مضاعفة الأجر عشر مرات ورفع الدرجات في الدنيا والآخرة.\nالمرجع: البخاري فتح الباري 6/408."
            78 -> "دعاء جامع يتضمن صلاح الدين والدنيا والآخرة، وسؤال الله تعالى أن يجعل الحياة زيادة في كل خير والموت راحة من كل شر.\nالمرجع: صحيح مسلم، كتاب 17، حديث 1472 (مسلم 2720)."
            79 -> "دعاء مبارك لإذهاب الهم والحزن، وسؤال الله أن يجعل القرآن ربيع القلوب ونور الصدور.\nالمرجع: مسند أحمد 1/391، وابن حبان 3/253."
            80 -> "دعاء لقضاء الدين والسلامة من الفقر والتوسل بأسماء الله الحسنى وصفاته العلا.\nالمرجع: صحيح مسلم 4/2084 (حديث 2713)."
            81 -> "دعاء لحسن العاقبة في الأمور كلها والحماية من خزي الدنيا وعذاب الآخرة.\nالمرجع: مسند أحمد 4/181، وصحيح ابن حبان 949، والحاكم 3/591."
            82 -> "دعاء للثبات على الدين والعزيمة على الرشد، وسؤال الله تعالى قلباً سليماً ولساناً صادقاً.\nالمرجع: سنن النسائي 1304، والترمذي 3407، ومسند أحمد 17114."
            83 -> "دعاء للاستعاذة من علم لا ينفع، ومن قلب لا يخشع، ومن نفس لا تشبع، ومن دعوة لا يستجاب لها.\nالمرجع: صحيح مسلم 4/2088 (حديث 2722)، والنسائي 5442، وأبو داود 1548."
            else -> "المرجع: البخاري ومسلم وغيرهما من كتب الحديث الصحيحة."
        }
    }
}
